<?php
include 'components/connect.php'; session_start(); $message=[]; $token=trim((string)($_GET['token']??$_POST['token']??'')); $valid=null;
if($token!==''){ $stmt=$conn->prepare("SELECT * FROM password_reset_tokens WHERE token_hash = ? AND used_at IS NULL AND expires_at > NOW() LIMIT 1"); $stmt->execute([hash('sha256',$token)]); $valid=$stmt->fetch(PDO::FETCH_ASSOC); }
if(isset($_POST['reset_password']) && $valid){ $pass=(string)($_POST['pass']??''); $confirm=(string)($_POST['cpass']??''); if(strlen($pass)<8)$message[]='Password must be at least 8 characters.'; elseif($pass!==$confirm)$message[]='Passwords do not match.'; else{$conn->prepare("UPDATE users SET password = ? WHERE id = ?")->execute([password_hash($pass,PASSWORD_DEFAULT),$valid['user_id']]);$conn->prepare("UPDATE password_reset_tokens SET used_at = NOW() WHERE id = ?")->execute([$valid['id']]);$message[]='Password updated. You can log in now.';$valid=null;} }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Set new password</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.1.1/css/all.min.css"><link rel="stylesheet" href="css/style.css"></head><body><?php include 'components/user_header.php'; ?><section class="form-container"><form method="post"><h3>set new password</h3><?php foreach($message as $m): ?><p class="message"><span><?= htmlspecialchars($m,ENT_QUOTES,'UTF-8'); ?></span></p><?php endforeach; ?><?php if($valid): ?><input type="hidden" name="token" value="<?= htmlspecialchars($token,ENT_QUOTES,'UTF-8'); ?>"><input class="box" type="password" name="pass" minlength="8" required placeholder="new password"><input class="box" type="password" name="cpass" minlength="8" required placeholder="confirm password"><input class="btn" type="submit" name="reset_password" value="update password"><?php elseif(!$message): ?><p class="message">This reset link is invalid or expired.</p><?php endif; ?><a class="option-btn" href="user_login.php">back to login</a></form></section><?php include 'components/footer.php'; ?><script src="js/script.js"></script></body></html>
